import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import { useAuth } from '../contexts/AuthContext';
import toast from 'react-hot-toast';

const ProblemList = () => {
  const [problems, setProblems] = useState([]);
  const [loading, setLoading] = useState(true);
  const { token } = useAuth();
  const navigate = useNavigate();

  useEffect(() => {
    fetchProblems();
  }, []);

  const fetchProblems = async () => {
    try {
      const response = await axios.get('http://localhost:5000/api/problems', {
        headers: { Authorization: `Bearer ${token}` }
      });
      setProblems(response.data.problems || []);
    } catch (error) {
      console.error('Error fetching problems:', error);
      toast.error('Failed to load problems');
    } finally {
      setLoading(false);
    }
  };

  const getDifficultyColor = (difficulty) => {
    switch (difficulty) {
      case 'Easy': return '#28a745';
      case 'Medium': return '#ffc107';
      case 'Hard': return '#dc3545';
      default: return '#6c757d';
    }
  };

  const handleProblemClick = (problemId) => {
    navigate(`/problems/${problemId}`);
  };

  if (loading) {
    return (
      <div style={styles.loadingContainer}>
        <div className="spinner"></div>
        <p>Loading problems...</p>
      </div>
    );
  }

  return (
    <div style={styles.container}>
      <div style={styles.header}>
        <h1 style={styles.title}>📚 Problems</h1>
        <p style={styles.subtitle}>Solve coding problems and improve your skills</p>
      </div>

      <div style={styles.list}>
        {problems.length === 0 ? (
          <div style={styles.emptyState}>
            <span style={styles.emptyIcon}>📭</span>
            <p>No problems available</p>
          </div>
        ) : (
          problems.map((problem) => (
            <div
              key={problem._id}
              style={styles.problemRow}
              onClick={() => handleProblemClick(problem._id)}
            >
              <div style={styles.rowContent}>
                <div style={styles.leftSection}>
                  <div style={styles.problemId}>#{problem._id}</div>
                  <div style={styles.problemTitle}>{problem.title}</div>
                  <div style={styles.problemDescription}>
                    {problem.description?.substring(0, 60)}...
                  </div>
                </div>
                <div style={styles.rightSection}>
                  <span style={{
                    ...styles.difficultyBadge,
                    backgroundColor: getDifficultyColor(problem.difficulty),
                    color: problem.difficulty === 'Medium' ? '#333' : 'white'
                  }}>
                    {problem.difficulty || 'Easy'}
                  </span>
                  <button style={styles.solveButton}>
                    Solve →
                  </button>
                </div>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

const styles = {
  container: {
    padding: '30px',
    maxWidth: '1000px',
    margin: '0 auto',
    minHeight: '100vh',
    background: '#f0f2f5',
  },
  header: {
    marginBottom: '30px',
  },
  title: {
    fontSize: '28px',
    fontWeight: 700,
    color: '#1a1a2e',
    marginBottom: '8px',
  },
  subtitle: {
    fontSize: '16px',
    color: '#666',
  },
  list: {
    display: 'flex',
    flexDirection: 'column',
    gap: '12px',
  },
  problemRow: {
    background: 'white',
    borderRadius: '12px',
    padding: '18px 24px',
    boxShadow: '0 2px 8px rgba(0,0,0,0.06)',
    cursor: 'pointer',
    transition: 'all 0.3s ease',
    border: '1px solid #e8e8e8',
    width: '100%',
  },
  rowContent: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    width: '100%',
  },
  leftSection: {
    display: 'flex',
    alignItems: 'center',
    gap: '20px',
    flex: 1,
  },
  problemId: {
    fontSize: '14px',
    fontWeight: 600,
    color: '#999',
    minWidth: '40px',
  },
  problemTitle: {
    fontSize: '18px',
    fontWeight: 600,
    color: '#1a1a2e',
    minWidth: '150px',
  },
  problemDescription: {
    fontSize: '14px',
    color: '#888',
    flex: 1,
  },
  rightSection: {
    display: 'flex',
    alignItems: 'center',
    gap: '16px',
  },
  difficultyBadge: {
    padding: '4px 14px',
    borderRadius: '20px',
    fontSize: '12px',
    fontWeight: 600,
    whiteSpace: 'nowrap',
  },
  solveButton: {
    padding: '8px 24px',
    background: '#FF8C00',
    color: 'white',
    border: 'none',
    borderRadius: '8px',
    fontSize: '14px',
    fontWeight: 600,
    cursor: 'pointer',
    transition: 'all 0.3s ease',
    whiteSpace: 'nowrap',
  },
  loadingContainer: {
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
    justifyContent: 'center',
    minHeight: '60vh',
  },
  emptyState: {
    textAlign: 'center',
    padding: '60px 20px',
    color: '#999',
  },
  emptyIcon: {
    fontSize: '48px',
    display: 'block',
    marginBottom: '12px',
  },
};

export default ProblemList;
